update articles set content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Kursus kahwin ialah kursus wajib untuk pasangan Muslim sebelum memohon nikah. Ia memberi ilmu asas rumah tangga seperti hukum nikah, tanggungjawab pasangan dan proses perkahwinan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Artikel ini merangkumi cara daftar, syarat dan lokasi kursus di seluruh Malaysia.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Apa itu Kursus Kahwin","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/kursus-kahwin/1787396416141-IN-KursusKahwin-Kelas-1024x576/high.webp","title":null,"data-caption":"SOURCE: UTUSAN MALAYSIA","data-caption-url":null}},{"type":"paragraph","content":[{"text":"Kursus kahwin atau Kursus Pra Perkahwinan adalah sebuah program wajib yang disediakan khusus untuk bakal pengantin Muslim di Malaysia.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kursus ini bertujuan memberikan maklumat asas, bimbingan awal dan pendedahan penting kepada bakal suami dan isteri sebelum melangkah ke alam rumahtangga.","type":"text"}]},{"type":"paragraph","content":[{"text":"Ia dilaksanakan bertujuan untuk mengurangkan permasalahan rumahtangga dan kadar perceraian, melalui penyampaian ilmu yang berkaitan dengan kehidupan berumahtangga.","type":"text"}]},{"type":"paragraph","content":[{"text":"Sepanjang kursus, peserta akan mempelajari pelbagai topik seperti hukum-hakam perkahwinan, pengurusan hubungan suami isteri, interaksi dalam keluarga, proses serta prosedur perkahwinan, dan juga kisah-kisah benar rumahtangga yang boleh dijadikan sempadan dan teladan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pelaksanaan kursus kahwin ini adalah di bawah tanggungjawab Jabatan Agama Islam Negeri (JAIN), Di sesetengah negeri, kursus dianjurkan terus oleh pihak jabatan agama, manakala di negeri lain, pelaksanaannya dibantu oleh syarikat-syarikat swasta yang dilantik dan diiktiraf.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Kandungan Kursus Kahwin","type":"text"}]},{"type":"paragraph","content":[{"text":"Tempoh pelaksanaan kursus adalah selama dua hari (13 jam keseluruhan tajuk). Terdapat beberapa kandungan kursus kahwin yang perlu anda jalani semasa program ini. Antaranya seperti:","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tasawwur Islam – ","type":"text","marks":[{"type":"bold"}]},{"text":"Penerangan asas tentang Islam iaitu aqidah, syariah dan akhlak. Peserta belajar apa yang membatalkan aqidah dan cara menjaga pegangan yang betul dalam rumah tangga.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Perkahwinan – ","type":"text","marks":[{"type":"bold"}]},{"text":"Fahami tujuan dan hikmah perkahwinan, hukum dan ","type":"text"},{"text":"rukun nikah","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"/artikel/nikah-undang-undang/rukun-nikah","class":null,"target":"_self"}}]},{"text":" serta panduan memilih pasangan. Turut terangkan peranan wali dan perkara penting yang menentukan sahnya perkahwinan.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Prosedur perkahwinan – ","type":"text","marks":[{"type":"bold"}]},{"text":"Panduan langkah demi langkah untuk mohon kebenaran berkahwin, daftar nikah dan dapatkan Kad Nikah, termasuk kesalahan dan denda di bawah undang-undang keluarga Islam.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tanggungjawab suami isteri – ","type":"text","marks":[{"type":"bold"}]},{"text":"Ringkasan tugas dan peranan suami dan isteri untuk membina keluarga bahagia, termasuk tanggungjawab ketika mengurus kehamilan dan kelahiran anak.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Komunikasi suami isteri – ","type":"text","marks":[{"type":"bold"}]},{"text":"Cara berkomunikasi dengan baik dalam rumah tangga iaitu cara bercakap, bahasa tubuh dan kesan komunikasi yang tidak sihat.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pengurusan kewangan – ","type":"text","marks":[{"type":"bold"}]},{"text":"Belajar urus duit sebelum dan selepas kahwin iaitu bajet, aliran tunai, pinjaman dan kesannya pada keharmonian rumah tangga.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pengurusan kesihatan keluarga – ","type":"text","marks":[{"type":"bold"}]},{"text":"Penerangan asas tentang kesihatan fizikal, mental dan spiritual, termasuk ilmu tentang hubungan suami isteri, kehamilan, penjagaan bayi dan pemeriksaan kesihatan.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pengurusan stres dan konflik – ","type":"text","marks":[{"type":"bold"}]},{"text":"Cara kenal pasti stres dan konflik dalam perkahwinan serta teknik menangani masalah. Termasuk bila dan bagaimana dapatkan bantuan runding cara.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pembuburan perkahwinan – ","type":"text","marks":[{"type":"bold"}]},{"text":"Fahami sebab dan proses perceraian menurut syarak dan undang-undang, serta kesan dan hukuman jika berlaku kesalahan.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Majlis akad nikah dan walimatulurus – ","type":"text","marks":[{"type":"bold"}]},{"text":"Panduan lengkap sebelum, semasa dan selepas akad nikah dan majlis kenduri, termasuk perkara yang perlu dibuat dan perlu dielakkan.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Bayaran Yuran","type":"text"}]},{"type":"paragraph","content":[{"text":"Tiada satu kadar untuk seluruh Malaysia. Setiap negeri menetapkan sendiri, dan pada 26 Ogos 2026 angkanya bermula daripada percuma di Melaka sehingga RM180 di Wilayah Persekutuan. Empat bidang kuasa tidak menerbitkan sebarang kadar langsung.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pulau Pinang naik pada 1 September 2026. JHEAIPP mengumumkan di portal e-Munakahatnya sendiri bahawa yuran menjadi RM120 seorang mulai tarikh itu, dan kursus yang diadakan sebelum 1 September kekal RM100. Kalau tarikh kursus anda jatuh dalam minggu itu, apa yang anda bayar bergantung pada hari kursus, bukan hari anda mendaftar.","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Negeri","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Yuran seorang","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Di mana kadar itu tersiar","type":"text"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Disemak","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Perlis","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM100","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"SPPIM: 2 kursus tersenarai, satu penganjur","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"26 Ogos 2026","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kedah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM100","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"SPPIM: 135 kursus, 19 penganjur, semuanya RM100","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"26 Ogos 2026","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Pulau Pinang","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM100, naik ke RM120 mulai 1 Sep 2026","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"JHEAIPP, portal e-Munakahat","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"26 Ogos 2026","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Perak","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM100","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"SPPIM: 27 kursus, 9 penganjur, semuanya RM100","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"26 Ogos 2026","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"ro