eCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"26 Ogos 2026","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Terengganu","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"RM80","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"SPPIM: 12 kursus, semuanya anjuran jabatan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"26 Ogos 2026","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Kelantan","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada kadar tersiar","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"JHEAIK; angka rasmi terakhir RM70, kursus masjid Sep 2025","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"26 Ogos 2026","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Sabah","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada kadar tersiar","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"JHEAINS iKursusKahwin, ruangan \"Yuran Kursus\" tanpa angka","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"26 Ogos 2026","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Sarawak","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"Tiada kadar semasa tersiar","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"JAIS Sarawak; angka terakhir RM80, Bahagian Kuching Jun 2024","type":"text"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"text":"26 Ogos 2026","type":"text"}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Empat Negeri Yang Tidak Menerbitkan Kadar","type":"text"}]},{"type":"paragraph","content":[{"text":"Kami semak portal rasmi keempat-empatnya pada 26 Ogos 2026. Angka itu memang tiada, dan itu sendiri satu jawapan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pahang. Portal Jabatan Agama Islam Pahang memaparkan notis \"Portal Sedang Diselenggara\". Sistem Permohonan Kursus Pra Perkahwinan Negeri Pahang wujud, tetapi ia meminta nombor kad pengenalan dan kata laluan sebelum sebarang maklumat kursus keluar.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kelantan. Permohonan nikah melalui e-Qaryah, tetapi yuran kursus tidak tersiar. Angka rasmi terakhir yang kami jumpa ialah RM70 seorang bagi satu kursus MBKPI anjuran masjid dengan kerjasama JHEAIK pada September 2025. Itu kadar satu penganjur pada satu tarikh, bukan kadar negeri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Sabah. Portal iKursusKahwin JHEAINS ada ruangan bertajuk \"Yuran Kursus\", dan ruangan itu cuma menyatakan bayaran tidak dikembalikan. Tiada angka. Jadual kursus setiap daerah pula memaparkan \"Slot Belum Dibuka\". JHEAINS memang menerbitkan senarai kadar fi rasmi, tetapi senarai itu meliputi kebenaran berkahwin, pendaftaran nikah dan kad nikah, bukan kursus.","type":"text"}]},{"type":"paragraph","content":[{"text":"Sarawak. Pendaftaran dan bayaran melalui sistem KISWA. Halaman \"Tarikh Kursus Pra Perkahwinan\" di portal JAIS Sarawak masih membawa jadual 2013. Angka terakhir yang jabatan itu sendiri terbitkan ialah RM80 seorang bagi kursus Bahagian Kuching pada Jun 2024.","type":"text"}]},{"type":"paragraph","content":[{"text":"Bagi keempat-empat negeri ini, hubungi pejabat agama daerah anda dan tanya sebelum mendaftar. Sesiapa yang memberi anda angka bulat untuk Sabah hari ini sedang meneka.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Di Mana Anda Mendaftar Dan Membayar","type":"text"}]},{"type":"paragraph","content":[{"text":"Sembilan bidang kuasa menggunakan SPPIM: Perlis, Kedah, Perak, Selangor, Wilayah Persekutuan, Negeri Sembilan, Melaka, Johor dan Terengganu. Di situ yuran tersiar pada setiap kursus, penganjur demi penganjur, dan itulah sebabnya Johor boleh menunjukkan RM150 dan RM165 pada minggu yang sama.","type":"text"}]},{"type":"paragraph","content":[{"text":"Lima yang lain menggunakan sistem sendiri: Pulau Pinang (e-Munakahat), Pahang (Sistem Permohonan Kursus Pra Perkahwinan Negeri Pahang), Sabah (iKursusKahwin), Sarawak (KISWA) dan Kelantan (melalui pejabat agama daerah).","type":"text"}]},{"type":"paragraph","content":[{"text":"Duit yang sudah masuk susah ditarik balik. JHEAINS Sabah menyatakan yuran yang telah dibayar tidak dikembalikan dan tarikh tidak boleh ditukar. Pulau Pinang pula tidak memulangkan bayaran jika peserta gagal hadir tanpa makluman, dan slip bayaran perlu dimuat naik dalam tempoh satu jam atau permohonan dibatalkan sendiri dan slot dilepaskan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Yuran kursus juga bukan kos penuh urusan nikah. Ia berasingan daripada bayaran kebenaran berkahwin, pendaftaran nikah dan kad perakuan nikah, yang ada kadar sendiri di setiap negeri.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Kenapa Tiada Satu Nombor Untuk Seluruh Malaysia","type":"text"}]},{"type":"paragraph","content":[{"text":"Garis panduan JAKIM bagi prosedur pentadbiran perkahwinan mewajibkan Sijil Kursus Pra Perkahwinan MBKPPI sebelum kebenaran berkahwin diluluskan, tetapi dokumen itu tidak menyebut sebarang yuran. Halaman kursus pra perkahwinan di portal JAKIM pun tidak menyiarkan kadar. Yuran diputuskan di peringkat negeri, dan di negeri yang membenarkan penganjur swasta, ia diputuskan penganjur demi penganjur.","type":"text"}]},{"type":"paragraph","content":[{"text":"Sebab itu julatnya luas: RM80 di Terengganu, RM100 rata di Perlis, Kedah, Perak dan Selangor, RM120 di Wilayah Persekutuan, RM165 bagi sesetengah kursus Johor, dan RM180 di satu penganjur di wilayah yang sama. Artikel yang memberi anda satu julat kemas untuk seluruh negara sedang meratakan perbezaan yang justru menentukan berapa anda bayar.","type":"text"}]},{"type":"paragraph","content":[{"text":"Semak kadar untuk tarikh dan lokasi kursus anda sendiri sebelum mendaftar. Angka di atas disemak pada 26 Ogos 2026 dan boleh berubah tanpa pengumuman. Pulau Pinang buktinya.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Tempoh Sah Sijil Kahwin","type":"text"}]},{"type":"paragraph","content":[{"text":"Semua negeri tidak menetapkan tempoh luput sijil, kecuali Johor dan Melaka. Bagi permohonan nikah di kedua-dua negeri ini, tarikh perkahwinan mestilah dalam tempoh 10 tahun daripada tarikh kursus dihadiri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Prosedur ini berkuat kuasa untuk peserta yang mengikuti kursus selepas 2 Februari 2024 (Johor) dan selepas 1 Jun 2023 (Melaka).","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Cara Daftar Kursus Kahwin","type":"text"}]},{"type":"heading","attrs":{"level":4},"content":[{"text":"Pendaftaran Kursus","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Buka laman SPPIM ","type":"text"},{"text":"(","type":"text","marks":[{"type":"bold"}]},{"text":"https://www.sppim.gov.my","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://www.sppim.gov.my/v2/home","class":null,"target":"_blank"}},{"type":"bold"}]},{"text":") ","type":"text","marks":[{"type":"bold"}]},{"text":"dan klik ","type":"text"},{"text":"Permohonan Baru","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pilih ","type":"text"},{"text":"Jenis Kursus","type":"text","marks":[{"type":"bold"}]},{"text":", ","type":"text"},{"text":"Negeri","type":"text","marks":[{"type":"bold"}]},{"text":", ","type":"text"},{"text":"Daerah","type":"text","marks":[{"type":"bold"}]},{"text":", serta tetapkan ","type":"text"},{"text":"Tarikh Dari – Tarikh Hingga","type":"text","marks":[{"type":"bold"}]},{"text":", kemudian klik ","type":"text"},{"text":"Seterusnya","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pilih kursus yang ingin disertai dari senarai yang dipaparkan dan klik ","type":"text"},{"text":"Seterusnya","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lengkapkan maklumat peserta seperti nama, tarikh lahir, jantina, warganegara, telefon dan e-mel.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pilih jenis pengenalan (IC baru, IC lama, Polis, Tentera, Pasport atau lain-lain) dan klik ","type":"text"},{"text":"Seterusnya","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mesej makluman akan dipaparkan. Klik ","type":"text"},{"text":"OK","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pilih ","type":"text"},{"text":"Cara Bayaran","type":"text","marks":[{"type":"bold"}]},{"text":" – Tunai (kecuali Selangor), Pindahan Atas Talian atau DuitNow.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jika pindahan atau DuitNow, masukkan ","type":"text"},{"text":"No. Rujukan Slip","type":"text","marks":[{"type":"bold"}]},{"text":" dan ","type":"text"},{"text":"Muat Naik Slip Bayaran","type":"text","marks":[{"type":"bold"}]},{"text":" ","type":"text"},{"text":"(PDF/JPG/PNG/GIF)","type":"text","marks":[{"type":"bold"}]},{"text":", kemudian klik ","type":"text"},{"text":"Seterusnya","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tanda ✔ pada ","type":"text"},{"text":"Saya Bersetuju","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Klik ","type":"text"},{"text":"Hantar","type":"text","marks":[{"type":"bold"}]},{"text":" untuk menghantar permohonan.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Paparan “Pendaftaran Berjaya” akan muncul.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Klik ","type":"text"},{"text":"Cetak Slip Pendaftaran Kursus","type":"text","marks":[{"type":"bold"}]},{"text":" jika diperlukan.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Semak emel untuk notifikasi pendaftaran yang dihantar.","type":"text"}]}]}]},{"type":"image","attrs":{"alt":"","src":