,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Imbas ","type":"text"},{"text":"Kod QR","type":"text","marks":[{"type":"bold"}]},{"text":" yang diberikan penceramah/penganjur selepas setiap sesi kursus mengikut tajuk.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Masukkan ","type":"text"},{"text":"No. Pengenalan","type":"text","marks":[{"type":"bold"}]},{"text":" dan klik ","type":"text"},{"text":"Semak","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Paparan mesej “Kehadiran berjaya dicatatkan” akan dipaparkan.","type":"text"}]}]}]},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/kursus-kahwin/1787396437841-IN-KursusKahwin-15-1024x576/high.webp","title":null,"data-caption":"SOURCE: SPPIM","data-caption-url":null}},{"type":"heading","attrs":{"level":2},"content":[{"text":"Penilaian Peserta","type":"text"}]},{"type":"paragraph","content":[{"text":"1. Penilaian melalui QR Code","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Imbas ","type":"text"},{"text":"Kod QR","type":"text","marks":[{"type":"bold"}]},{"text":" yang disediakan penganjur bagi sesi kursus yang telah selesai.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lengkapkan penilaian yang dipaparkan.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"2. Penilaian melalui Web","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Masukkan ","type":"text"},{"text":"No. Pengenalan / E-mel","type":"text","marks":[{"type":"bold"}]},{"text":" dan ","type":"text"},{"text":"No. Rujukan Pendaftaran","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Klik ikon penilaian pada senarai tajuk kursus.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Klik ","type":"text"},{"text":"Seterusnya","type":"text","marks":[{"type":"bold"}]},{"text":" selepas kehadiran disahkan.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lengkapkan penilaian dan klik ","type":"text"},{"text":"Hantar","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]}]},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/kursus-kahwin/1787396439163-IN-KursusKahwin-16-1024x576/high.webp","title":null,"data-caption":"SOURCE: SPPIM","data-caption-url":null}},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/kursus-kahwin/1787396440600-IN-KursusKahwin-17-1024x576/high.webp","title":null,"data-caption":"SOURCE: SPPIM","data-caption-url":null}},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/kursus-kahwin/1787396442150-IN-KursusKahwin-18-1024x576/high.webp","title":null,"data-caption":"SOURCE: SPPIM","data-caption-url":null}},{"type":"heading","attrs":{"level":2},"content":[{"text":"Lokasi Kursus Kahwin Seluruh Malaysia","type":"text"}]},{"type":"paragraph","content":[{"text":"Anda boleh semak lokasi-lokasi terpilih kursus kahwin di setiap negeri di sini “Direktor Penganjur Kursus” : ","type":"text"},{"text":"https://sppim.gov.my/v2/online/pra-kahwin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://sppim.gov.my/v2/online/pra-kahwin","class":null,"target":"_blank"}}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Kepentingan Sijil Kursus Kahwin","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Syarat wajib untuk permohonan nikah","type":"text","marks":[{"type":"bold"}]},{"type":"hardBreak"},{"text":"Sijil kursus kahwin adalah dokumen yang diperlukan oleh Jabatan Agama Islam Negeri bagi meluluskan permohonan berkahwin. Tanpa sijil ini, permohonan tidak dapat diproses.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bukti peserta telah mendapat ilmu asas perkahwinan","type":"text","marks":[{"type":"bold"}]},{"type":"hardBreak"},{"text":"Sijil ini menunjukkan bahawa bakal pengantin telah menghadiri kursus dan memahami asas-asas penting seperti hukum nikah, tanggungjawab suami isteri, komunikasi, kewangan dan pengurusan rumah tangga.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Membantu pasangan membuat persediaan sebelum berkahwin","type":"text","marks":[{"type":"bold"}]},{"type":"hardBreak"},{"text":"Ia membuktikan bahawa peserta telah menerima pendedahan awal tentang cabaran dan realiti perkahwinan, sekali gus membantu membina rumahtangga yang lebih stabil dan harmoni.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Digunakan sebagai rujukan rasmi oleh jabatan agama","type":"text","marks":[{"type":"bold"}]},{"type":"hardBreak"},{"text":"Sijil ini menjadi rekod rasmi bahawa seseorang telah mengikuti kursus praperkahwinan mengikut piawaian modul yang ditetapkan oleh Jabatan Agama Islam.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Memudahkan urusan pendaftaran nikah di masa hadapan","type":"text","marks":[{"type":"bold"}]},{"type":"hardBreak"},{"text":"Sijil mempunyai tempoh sah yang panjang (tiada tarikh luput bagi kebanyakan negeri), jadi ia boleh digunakan walaupun permohonan nikah dibuat bertahun-tahun kemudian.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Kesimpulan","type":"text"}]},{"type":"paragraph","content":[{"text":"Kesimpulannya, kursus kahwin adalah penting sebagai ","type":"text"},{"text":"syarat nikah","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"/artikel/nikah-undang-undang/syarat-sah-nikah","class":null,"target":"_self"}}]},{"text":" dan persediaan awal untuk membina sebuah rumah tangga.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dengan mengetahui proses pendaftaran, syarat dan pusat kursus mengikut negeri, pasangan boleh mengurus permohonan nikah dengan lebih mudah.","type":"text"}]},{"type":"paragraph","content":[{"text":"Untuk sebarang pertanyaan atau maklumat lanjut berkenaan kursus kahwin ini, anda boleh rujuk pada pautan : ","type":"text"},{"text":"https://www.sppim.gov.my/v2/online/aduan/main","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://www.sppim.gov.my/v2/online/aduan/main","class":null,"target":"_blank"}}]}]},{"type":"paragraph","content":[{"text":"Artikel Lain:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Checklist Sewa Dewan Kahwin: Apa yang Perlu Ditanya Sebelum Bayar Deposit","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"https://hellokahwin.com/sewa-dewan-kahwin/","class":null,"target":"_self"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mas Kahwin Ikut Negeri: Negeri Mana Paling Tinggi & Paling Rendah?","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"https://hellokahwin.com/mas-kahwin-ikut-negeri/","class":null,"target":"_self"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Cara Buat Kad Kahwin Digital Sendiri – Lengkap Dengan Contoh & Template Percuma","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"https://hellokahwin.com/cara-buat-kad-kahwin-digital/","class":null,"target":"_self"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Borang Nikah: Borang Mana, Isi Apa, Hantar Ke Mana","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"/artikel/nikah-undang-undang/borang-nikah","class":null,"target":"_self"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lafaz Taklik: Apa Suami Baca Selepas Akad, dan Apa Ertinya","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"/artikel/nikah-undang-undang/lafaz-taklik","class":null,"target":"_self"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Taaruf Maksud: Apa Itu Taaruf dan Apa Bezanya dengan Bercinta","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"/artikel/sebelum-nikah/taaruf-maksud","class":null,"target":"_self"}}]}]}]}]}]}'::jsonb where id = '1c2e96ae-340f-4226-bb32-363da8cbe3d0';

-- tempat-honeymoon-di-malaysia  id=3dcdff4c-d262-4333-8a75-4f826a207918  270 top-level nodes, updated_at was 2026-08-26T17:09:28.572Z
update articles set content = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Tempat honeymoon di Malaysia sering menjadi pilihan pasangan kerana di sinilah bermulanya detik istimewa yang menetapkan rentak awal kehidupan berumahtangga.","type":"text"}]},{"type":"paragraph","content":[{"text":"Walaupun kedengaran klise, honeymoon adalah antara momen paling bermakna untuk berehat, mengenali pasangan dengan lebih dekat dan mencipta kenangan pertama bersama,","type":"text"}]},{"type":"paragraph","content":[{"text":"Malaysia mempunyai semua elemen untuk honeymoon sempurna daripada pulau tropika dan pantai yang tenang, hinggalah pergunungan sejuk serta sudut romantik yang cozy.","type":"text"}]},{"type":"paragraph","content":[{"text":"Sama ada anda pasangan pencinta pengembaraan, percutian santai atau romantik penuh emosi, Malaysia benar-benar menawarkan sesuatu untuk semua.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Senarai Tempat Honeymoon di Malaysia Paling Best","type":"text"}]},{"type":"paragraph","content":[{"text":"Berikut adalah pilihan tempat honeymoon di Malaysia yang terbaik dan sering menjadi tumpuan pasangan pengantin baharu.","type":"text"}]},{"type":"paragraph","content":[{"text":"Setiap destinasi ini menawarkan suasana romantik, pemandangan indah serta pengalaman istimewa untuk dinikmati berdua.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Pulau Pangkor, Perak","type":"text"}]},{"type":"image","attrs":{"alt":"tempat honeymoon di malaysia ","src":"https://images.hellokahwin.com/inspire/tempat-honeymoon-di-malaysia/1787395666446-IN-TempatHoneymoondiMalaysia-PulauPangkor/high.webp","title":null,"data-caption":"source: tripadvisor","data-caption-url":null}},{"type":"paragraph","content":[{"text":"Pulau Pangkor ialah salah tempat honeymoon di Malaysia, terkenal dengan aura romantik yang terhasil daripada gabungan pantai keemasan, air biru jernih, dan angin laut yang menenangkan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dikatakan nama Pangkor berasal daripada perkataan “Pang Ko” yang membawa maksud “Indah”, dan benar setiap sudut pula ini seperti dicipta khas untuk memanjakan pasangan yang ingin menikmati ketenangan dan privasi.","type":"text"}]},{"type":"paragraph","content":[{"text":"Keindahan yang paling menonjol terletak pada tiga pulau kecil iaitu Pangkor Laut, Pulau Mentagor dan Pulau Giam yang menjadi simbol dan eksklusiviti.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pulau Pangkor Laut, khususnya merupakan destinasi honeymoon bertaraf dunia yang menawarkan vila atas air, spa mewah dan pantai terpencil yang hanya boleh dinikmati oleh tetamu resort.","type":"text"}]},{"type":"paragraph","content":[{"text":"Selain pantai, lanskap pulau yang berbukit-bukau dan kehijauan alam semula jadi menjadikan Pangkor sesuai untuk pasangan yang ingin mengimbangi waktu romantik di pantai dengan sedikit aktiviti luar trekking dan eksplorasi.","type":"text"}]},{"type":"paragraph","content":[{"text":"Waktu Terbaik untuk Datang:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Februari – Ogos (cuaca cerah, ombak lebih tenang, pemandangan lebih memukau)","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Sesuai Untuk:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan yang mahu gabungan ketenangan + kemewahan","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Honeymoon yang mementingkan privasi, spa, dan pantai terpencil","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan yang suka aktiviti air tetapi dalam suasana tidak terlalu sesak","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Aktiviti Menarik untuk Dilakukan:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Trekking bersama ke Bukit Pangkor","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Snorkeling, diving, swimming & fishing","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Eksplorasi pantai tersembunyi seperti Turtle Beach","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lawatan ke Kuil Amman yang bersejarah","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Makan malam romantik di Emerald Bay dengan pemandangan sunset","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Hotel / Resort Terbaik:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"AVI Pangkor Beach Resort","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pangkor Sandy Beach Resort","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Anjungan Beach Resort","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Pulau Sipadan – Mabul, Sabah","type":"text"}]},{"type":"image","attrs":{"alt":"tempat honeymoon di malaysia ","src":"https://images.hellokahwin.com/inspire/tempat-honeymoon-di-malaysia/1787395668007-IN-TempatHoneymoondiMalaysia-PulauSipadanMabul-/high.webp","title":null,"data-caption":"source: pulau Mabul","data-caption-url":null}},{"type":"paragraph","content":[{"text":"Bagi pasangan yang menganggap lautan sebagai dunia kedua mereka, Pulau Sipadan adalah tempat honeymoon di Malaysia yang tiada tandingan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Terkenal sebagai salah satu tempat menyelam terbaik dunia, Sipadan memukau dengan barracuda tornado, penyu yang berenang bebas, terumbu karang warna-warni, dan air laut sebening kristal.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pulau Mabul yang berdekatan menjanjikan suasana yang lebih santai tetapi tetap eksklusif, lengkap dengan resort atas air yang sangat instagrammable sesuai untuk honeymoon berlatarkan panorama lautan yang tidak berpenghujung.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pasangan yang memilih Sipadan biasanya adalah mereka yang sukakan pengalaman unik dan penuh pengembaraan, namun masih ingin menikmati resort bertaraf dunia.","type":"text"}]},{"type":"paragraph","content":[{"text":"Waktu Terbaik untuk Datang:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"April – Disember (musim terbaik untuk diving)","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Sesuai Untuk:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan yang suka diving, snorkeling dan foto underwater","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Honeymoon yang berkonsepkan nature + adventure","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Aktiviti Menarik untuk Dilakukan:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Scuba diving di Barracuda Point","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Snorkeling untuk melihat penyu dan coral garden","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Photography underwater bersama pasangan","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Leisure beach walk di pulau-pulau sekitar","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Hotel / Resort Terbaik:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sipadan Kapalai Dive Resort","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mabul Water Bungalows","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sipadan-Mabul Resort (SMART)","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Cameron Highland, Pahang","type":"text"}]},{"type":"image","attrs":{"alt":"tempat honeymoon di malaysia ","src":"https://images.hellokahwin.com/inspire/tempat-honeymoon-di-malaysia/1787395669518-IN-TempatHoneymoondiMalaysia-CameronHighland/high.webp","title":null,"data-caption":null,"data-caption-url":null}},{"type":"paragraph","content":[{"text":"Cameron Highland ialah tempat honeymoon di Malaysia yang penuh ketenangan, kehangatan suasana kolonial, serta pemandangan hijau yang menyegarkan. Terletak `1500 meter dari aras laut, ia menawarkan cuaca sejuk yang romantik sesuai untuk pasangan yang mahu lari dari panas kota.","type":"text"}]},{"type":"paragraph","content":[{"text":"Di sini, anda boleh berjalan berpegangan tangan di ladang teh luas, menikmati scones panas dalam suasana ala England, melawat strawberi, atau meneroka Mossy Forest yang penuh mistik.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kehidupan di sini bergerak perlahan memberi ruang kepada pasangan untuk benar-benar menikmati masa bersama. Selain alam, Cameron Highland juga kaya dengan sejarah. Banyak banglo lama ditukar menjadi hotel butik yang sangat intim dan romantik.","type":"text"}]},{"type":"paragraph","content":[{"text":"Waktu Terbaik untuk Datang:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mac – Mei","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"September – November","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Sesuai Untuk:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan yang sukakan cuaca sejuk & suasana hijau yang tenang","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Honeymoon santai dengan elemen kolonial & nature","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Aktiviti Menarik untuk Dilakukan:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lawatan ke Boh Tea Plantation","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Petik strawberi di Big Red Strawberry Farm","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bergambar di Lavender Garden","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mossy Forest trekking","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Melawat muzium & time tunnel gallery","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Minum petang di English-style hotels","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Hotel / Resort Terbaik:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Cameron Highlands Resort","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lakehouse Cameron Highlands","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"ZEN By Stellar Cameron","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Pulau Perhentian, Terengganu","type":"text"}]},{"type":"image","attrs":{"alt":"tempat honeymoon di malaysia ","src":"https://images.hellokahwin.com/inspire/tempat-honeymoon-di-malaysia/1787395672347-IN-TempatHoneymoondiMalaysia-PulauPerhentian/high.webp","title":null,"data-caption":"source: tripadvisor","data-caption-url":null}},{"type":"paragraph","content":[{"text":"Jika anda dan pasangan inginkan pulau yang lebih sunyi, lebih natural dan lebih romantik tanpa gangguan komersial, maka Perhentian adalah destinasi paling sesuai. Ia terkenal dengan air laut yang sangat jernih sehingga anda boleh melihat ikan berenang dari atas bot.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pantainya halus, putih dan luas sesuai untuk sesi fotografi romantik. Perhentian terdiri daripada dua pulau utama iaitu Perhentian Kecil dan Perhentian Besar.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kedua-duanya menawarkan pengalaman berbeza. Pulau Kecil lebih meriah dengan kafe dan muzik malam, manakala Pulau Besar lebih tenang dan sesuai untuk honeymoon.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pulau ini juga menawarkan pengalaman snorkeling terbaik di Malaysia, lengkap dengan penyu, coral garden, dan baby shark yang jinak.","type":"text"}]},{"type":"paragraph","content":[{"text":"Waktu Terbaik untuk Datang:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"April – Oktober (musim terbaik, ombak tenang)","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Sesuai Untuk:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan yang mahu pulau sunyi & dekat dengan alam semula jadi","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Honeymoon santai tetapi penuh aktiviti air","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Aktiviti Menarik untuk Dilakukan:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Snorkeling & scuba diving","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Island hopping ke Redang","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Kayaking berdua","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Camping romantik di Teluk KK","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dinner tepi pantai","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Hotel / Resort Terbaik:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Alunan Resort","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"BuBu Long Beach Resort","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Summer Bay Lang Tengah Island Resort","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Pulau Redang, Terengganu","type":"text"}]},{"type":"image","attrs":{"alt":"tempat honeymoon di malaysia ","src":"https://images.hellokahwin.com/inspire/tempat-honeymoon-di-malaysia/1787395673596-IN-TempatHoneymoondiMalaysia-PulauRedang/high.webp","title":null,"data-caption":"source: holidaygogogo","data-caption-url":null}},{"type":"paragraph","content":[{"text":"Pulau Redang merupakan tempat honeymoon di Malaysia yang ikonik dengan air laut biru jernih, pantai berpasir putih dan suasana tropik yang tenang serta romantik.","type":"text"}]},{"type":"paragraph","content":[{"text":"Keindahan semula jadinya menjadikan pulau ini ideal bagi pasangan yang ingin berehat dan meluangkan masa berkualiti daripada kesibukan bandar.","type":"text"}]},{"type":"paragraph","content":[{"text":"Terletak kira-kira 45 kiometer dari Kuala Terengganu, Pulau Redang mudah diakses melalui perjalanan bot dari Jeti Shahbandar atau Jeti Merang, malah hanya sekitar 30 minit dari Pulau Perhentian, sesuai untuk percutian dua pulau dalam satu perjalanan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pulau ini berada dalam kawasan Pulau Redang Marine Park yang dilindungi, menjadikannya kaya dengan terumbu karang terpelihara serta hidupan marin eksotik, dan terkenal sebagai lokasi snorkeling serta scuba diving terbaik di Malaysia.","type":"text"}]},{"type":"paragraph","content":[{"text":"Selain pantai dan laut, Pulau Redang turut mempunyai hutan paya bakau yang penting dari segi ekologi serta menyimpan fosil tumbuhan berusia 250 juta tahun, menambah nilai sejarah dan keunikan pulau ini.","type":"text"}]},{"type":"paragraph","content":[{"text":"Waktu Terbaik untuk Datang:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"April – Oktober","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Sesuai Untuk:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan yang sukakan pantai tropika & laut jernih","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Honeymoon yang santai, romantik dan dekat dengan alam semula jadi","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Peminat snorkeling, scuba diving dan marine life","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Aktiviti Menarik untuk Dilakukan:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Snorkeling dan scuba diving di Pulau Redang Marine Park","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Makan malam romantik di tepi pantai resort","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Boat trip mengelilingi pulau dan pulau-pulau kecil berhampiran","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bersantai di pantai Teluk Dalam, Pasir Panjang & Pasir Telok Kalong","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Aktiviti berkelah, bergambar dan berenang di air cetek","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lawatan santai ke kawasan hutan paya bakau","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Hotel / Resort Terbaik:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The Taaras Beach & Spa Resort","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Laguna Redang Island Resort","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Berjaya Redang Resort","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Mulu, Sarawak","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/tempat-honeymoon-di-malaysia/1787395675079-IN-TempatHoneymoonDiMalaysia-Mulu/high.webp","title":null,"data-caption":"SOURCE: RIVER JUNKIE","data-caption-url":null}},{"type":"paragraph","content":[{"text":"Honeymoon di Sarawak bukan sekadar percutian biasa, sebaliknya sebuah perjalanan penuh makna yang menggabungkan cinta, pengembaraan dan keindahan alam semula jadi.","type":"text"}]},{"type":"paragraph","content":[{"text":"Bagi pasangan yang mahukan pengalaman bulan madu yang berbeza daripada kebiasaan resort pantai Mulu, Sarawak tampil sebagai destinasi yang unik dan luar biasa.","type":"text"}]},{"type":"paragraph","content":[{"text":"Terletak di pedalaman Sarawak, Gunung Mulu National Park merupakan tapak Warisan Dunia UNESCO yang terkenal dengan hutan hujan purba, formasi batu kapur dramatik dan sistem gua terbesar di dunia.","type":"text"}]},{"type":"paragraph","content":[{"text":"Waktu Terbaik untuk Datang:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jun – September (musim lebih kering dan sesuai untuk aktiviti luar)","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Sesuai Untuk:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan yang sukakan honeymoon berkonsepkan adventure & nature","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pencinta alam semula jadi dan pengalaman unik","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Aktiviti Menarik untuk Dilakukan:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Teroka Gunung Mulu National Park (Tapak Warisan Dunia UNESCO)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lawatan ke gua terkenal seperti Deer Cave, Clearwater Cave & Lang’s Cave","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mendaki The Pinnacles","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jungle trekking dan canopy walk","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Menyaksikan ribuan kelawar keluar dari gua pada waktu senja","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Hotel / Resort Terbaik:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mulu Marriott Resort & Spa","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Borneo Eagle Resort","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Borneo Sepilok Rainforest Resort","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Langkawi, Kedah","type":"text"}]},{"type":"image","attrs":{"alt":"tempat honeymoon di malaysia ","src":"https://images.hellokahwin.com/inspire/tempat-honeymoon-di-malaysia/1787395676391-IN-TempatHoneymoondiMalaysia-Langkawi/high.webp","title":null,"data-caption":"Source: focus malaysia","data-caption-url":null}},{"type":"paragraph","content":[{"text":"Langkawi sering digelar Permata Kedah dan sememangnya layak menjadi impian sebagai tempat honeymoon di Malaysia. Pulau ini menawarkan gabungan sempurna antara pantai tropika, resort mewah, pengalaman romantik dan aktiviti alam semula jadi.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dari pasir putih Pantai Cenang hingga ke heningan Teluk Datai, Langkawi memberi ruang kepada pasangan untuk menikmati cinta dalam suasana yang eksklusif dan menenangkan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Sunset di Langkawi terkenal antara yang tercantik di Malaysia, menjadikannya lokasi ideal untuk detik romantik berdua.","type":"text"}]},{"type":"paragraph","content":[{"text":"Waktu Terbaik untuk Datang:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"November – April (cuaca lebih kering dan sesuai untuk aktiviti pantai)","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Sesuai Untuk:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan yang mahukan honeymoon pantai & resort mewah","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pencinta sunset, spa dan percutian santai","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Honeymoon pertama atau anniversary trip","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Aktiviti Menarik untuk Dilakukan:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Island hopping & sunset cruise","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Naik Langkawi Cable Car dan berjalan di SkyBridge","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Makan malam romantik di tepi pantai","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Spa dan urutan pasangan","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bersantai di Pantai Cenang atau Pantai Tengah","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Hotel / Resort Terbaik:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ambong Rainforest Retreat","type":"text"}]}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The Danna Langkawi Resort & Beach Villas","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The Datai Langkawi","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Japanese Village, Bentong","type":"text"}]},{"type":"image","attrs":{"alt":"tempat honeymoon di malaysia ","src":"https://images.hellokahwin.com/inspire/tempat-honeymoon-di-malaysia/1787395677884-IN-TempatHoneymoondiMalaysia-JapaneseVillageBenton/high.webp","title":null,"data-caption":"source: go where","data-caption-url":null}},{"type":"paragraph","content":[{"text":"Japanese Village di Bukit Tinggi menawarkan pengalaman bulan madu unik dengan suasana Jepun yang tenang dan damai.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dikeliling Taman Zen, kolam koi dan bunyi air terjun kecil, tempat honeymoon di Malaysia ini sesuai untuk pasangan yang mahu berehat sepenuhnya dari kesibukan dunia luar.","type":"text"}]},{"type":"paragraph","content":[{"text":"Suasana romantik ala Jepun menjadikan setiap langkah terasa perlahan dan penuh ketenangan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Waktu Terbaik untuk Datang:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sepanjang tahun (cuaca sejuk dan nyaman, sesuai untuk berjalan santai)","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Sesuai Untuk:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan yang mahukan honeymoon tenang & privasi","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pencinta budaya Jepun dan alam semula jadi","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Short romantic getaway berhampiran Kuala Lumpur","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Aktiviti Menarik untuk Dilakukan:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sertai upacara minum teh Jepun (tea ceremony)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bersiar-siar di taman Zen dan kolam koi","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Spa dan urutan ala Jepun","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bergambar dengan kimono","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Menikmati suasana hutan yang mendamaikan","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Hotel / Resort Terbaik:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Gibbon Retreat Bentong","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The Chateau Spa & Wellness Retreat","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Colmar Tropicale Resort","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Cherating, Pahang","type":"text"}]},{"type":"image","attrs":{"alt":"tempat honeymoon di malaysia ","src":"https://images.hellokahwin.com/inspire/tempat-honeymoon-di-malaysia/1787395679094-IN-TempatHoneymoondiMalaysia-Cherating/high.webp","title":null,"data-caption":"source: traveloka","data-caption-url":null}},{"type":"paragraph","content":[{"text":"Honeymoon di Cherating, Pahang menawarkan suasana yang ideal untuk berehat dan menikmati masa berdua.","type":"text"}]},{"type":"paragraph","content":[{"text":"Antara tarikan Istimewa ialah Santuari Penyu Cherating, di mana pasangan dapat menyaksikan usaha pemeliharaan penyu dan menghargai keindahan alam. Pada waktu malam pula, pengalaman menjadi lebih magis dengan Kelip-Kelip Sungai Cherating, aktiviti bot romantik yang paling sesuai dinikmati antara Julai hingga Oktober.","type":"text"}]},{"type":"paragraph","content":[{"text":"Ditambah dengan keindahan Pantai Cherating sepanjang hampir 8 kilometer dan aktiviti pantai menyeronokkan di Kam’s Surf Shack seperti surfing dan kite surfing, honeymoon di Cherating terasa seimbang, ringkas, romantik dan penuh kenangan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Waktu Terbaik untuk Datang:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mac – September","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Julai – Oktober (waktu terbaik untuk melihat kelip-kelip)","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Sesuai Untuk:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan yang mahukan honeymoon santai & dekat dengan alam","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pencinta pantai, hidupan liar dan pengalaman semula jadi","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Aktiviti Menarik untuk Dilakukan:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lawatan ke Santuari Penyu Cherating","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Menyusuri Kelip-Kelip Sungai Cherating pada waktu malam","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bersantai di Pantai Cherating","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Aktiviti pantai di Kam’s Surf Shack (kite surfing, windsurfing, surfing)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Berkelah dan menikmati sunset di tepi pantai","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Hotel / Resort Terbaik:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Club Med Cherating Beach Resort","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Royale Chulan Cherating","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The Kasturi Resort Cherating","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Janda Baik, Pahang","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/tempat-honeymoon-di-malaysia/1787395680452-IN_E2_80_94TempatHoneymoondiMalaysia-JandaBaik/high.webp","title":null,"data-caption":"SOURCE: Janda Baik ATTRACTION","data-caption-url":null}},{"type":"paragraph","content":[{"text":"Janda Baik ialah kawasan tanah tinggi yang tenang di Banjaran Titiwangsa, Pahang, hanya sekitar 45 minit dari Kuala Lumpur.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dengan cuaca sejuk nyaman, suasana kampung Melayu yang damai, hutan hijau dan sungai gunung yang jernih, destinasi ini sangat sesuai untuk pasangan yang menginginkan honeymoon romantik dan dekat dengan alam.","type":"text"}]},{"type":"paragraph","content":[{"text":"Berlatarkan kisah legenda tentang seorang balu berhati mulia, Janda Baik masih mengekalkan aura ketenangan dan keramahan hingga kini.","type":"text"}]},{"type":"paragraph","content":[{"text":"Honeymoon di sini menawarkan pengalaman desa yang tulen menikmati pemandangan gunung, bunyi aliran sungai serta kehijauan alam yang menyegarkan jiwa.","type":"text"}]},{"type":"paragraph","content":[{"text":"Waktu Terbaik untuk Datang:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sepanjang tahun","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Paling ideal: Mac – September (kurang hujan, sesuai untuk aktiviti luar)","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Sesuai Untuk:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan yang mahukan honeymoon alam semula jadi & tenang","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pencinta desa, sungai, hutan dan cuaca sejuk","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Honeymoon santai, cozy dan tidak klise","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Aktiviti Menarik untuk Dilakukan:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Berkelah dan mandi sungai di kawasan air jernih","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Hiking ke air terjun seperti Ulu Tampit & Chemperoh","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rafting di Sungai Benus","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Berbasikal dan nature walk di kampung","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lawatan ke ladang organik, fig farm & kebun bun","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Spa tradisional dan kolam air panas","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Hotel / Resort Terbaik:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tiarasa Escapes Glamping Resort Janda Baik","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Kebun Rimba Private Estate","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"VanaVasa Resort Janda Baik","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Pantai Teluk Kemang, Port Dickson","type":"text"}]},{"type":"image","attrs":{"alt":"tempat honeymoon di malaysia","src":"https://images.hellokahwin.com/inspire/tempat-honeymoon-di-malaysia/1787395682392-IN_E2_80_94TempatHoneymoondiMalaysia-PantaiTelukKe/high.webp","title":null,"data-caption":"SOURCE: BERITA HARIAN","data-caption-url":null}},{"type":"paragraph","content":[{"text":"Pantai Teluk Kemang merupakan antara pantai paling popular dan meriah di Port Dickson, terletak hanya sekitar 9 minit dari Lexis Hibiscus dan mudah diakses dari pusat bandar.","type":"text"}]},{"type":"paragraph","content":[{"text":"Lokasinya yang strategik menjadikan tempat honeymoon di Malaysia ini pilihan ideal untuk pasangan yang mahukan honeymoon ringkas, santai, dan tidak memerlukan perjalanan jauh.","type":"text"}]},{"type":"paragraph","content":[{"text":"Tempat honeymoon di Malaysia ini terkenal sebagai syurga sukan air, menawarkan pengalaman seperti jet ski, banana boat, parasailing, kayaking dan wind-surfing, selain berenang atau sekadar bersantai menikmati angin laut.","type":"text"}]},{"type":"paragraph","content":[{"text":"Menikmati hidangan tempatan sambil mendengar bunyi ombak dan angin laut menjadikan suasana lebih santai dan romantik.","type":"text"}]},{"type":"paragraph","content":[{"text":"Waktu Terbaik untuk Datang:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"April – September","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Hari bekerja (kurang sesak berbanding hujung minggu & cuti umum)","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Sesuai Untuk:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Honeymoon ringkas & santai","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan yang sukakan pantai dan sukan air","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Percutian romantik bajet dan mudah diakses","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Aktiviti Menarik untuk Dilakukan:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jet ski, banana boat & parasailing","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Kayaking dan wind-surfing","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Berenang dan bersantai di pantai","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Speedboat tour ke pantai atau pulau kecil berhampiran","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Menikmati makanan laut dan street food tempatan","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Hotel / Resort Terbaik:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lexis Hibiscus Port Dickson","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Avillion Port Dickson","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Grand Lexis Port Dickson","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Sabah River Safari, Kinabatangan","type":"text"}]},{"type":"paragraph","content":[{"text":"Sabah River Safari menawarkan pengalaman bulan madu yang unik menyusuri sungai sambil menikmati keindahan hutan hujan dan hidupan liar Borneo.","type":"text"}]},{"type":"paragraph","content":[{"text":"Suasana yang sunyi dan mendamaikan menjadikan pengalaman ini sangat istimewa untuk pasangan yang sukakan alam semula jadi.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pelayaran sungai memberi peluang melihat monyet proboscis, burung eksotik dan kelip-kelip yang berkelip indah pada waktu malam.","type":"text"}]},{"type":"paragraph","content":[{"text":"Waktu Terbaik untuk Datang:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mac hingga Oktober (musim kering) – cuaca lebih baik dan aktiviti sungai lebih selesa","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Awal pagi dan lewat petang – waktu terbaik melihat hidupan liar di sepanjang Sungai Kinabatangan","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Elakkan musim tengkujuh (November–Februari) kerana paras air sungai tinggi dan hujan kerap","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Sesuai Untuk:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan pengantin baru yang sukakan alam semula jadi dan ketenangan","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Honeymoon konsep eco-tourism dan adventure romantik","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan yang ingin lari daripada kesibukan bandar dan menikmati privasi","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pencinta fotografi alam dan pengalaman eksklusif berdua","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Aktiviti Menarik untuk Dilakukan:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pelayaran romantik menyusuri Sungai Kinabatangan sambil menikmati pemandangan hutan hujan tropika","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Melihat hidupan liar eksotik seperti orang utan, monyet proboscis, gajah pygmy Borneo dan burung enggang","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Night safari untuk pengalaman malam yang lebih mendebarkan dan unik","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jungle walk berdua sambil mengenali flora dan fauna tempatan","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Menikmati makan malam romantik di lodge berlatarbelakangkan alam semula jadi","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Hotel / Resort Terbaik:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Kinabatangan Wetlands Resort","type":"text"}]}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bungaraya Island Resort","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Borneo Natural Sukau Bilit Resort","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Kundasang, Sabah","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/tempat-honeymoon-di-malaysia/1787395683603-IN-TempatHoneymoondiMalaysia-Kundasang/high.webp","title":null,"data-caption":"source: on tour malaysia","data-caption-url":null}},{"type":"paragraph","content":[{"text":"Kundasang terkenal dengan pemandangan Gunung Kinabalu yang megah dan suasana sejuk yang menyegarkan. Kabus pagi, ladang hijau dan udara dingin menjadikan tempat ini sangat romantik untuk pasangan yang sukakan suasana gunung.","type":"text"}]},{"type":"paragraph","content":[{"text":"Di sini, pasangan boleh bangun pagi dengan pemandangan gunung, menikmati kopi panas bersama dan bersiar-siar dalam suasana desa yang damai. Kundasang memberikan ketenangan yang sukar ditemui di bandar.","type":"text"}]},{"type":"paragraph","content":[{"text":"Waktu Terbaik untuk Datang:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Disember – Februari (cuaca sejuk dan pemandangan gunung lebih jelas)","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Sesuai Untuk:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan pencinta gunung & cuaca sejuk","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Honeymoon alam semula jadi & fotografi","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan yang sukakan suasana desa dan tenang","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Aktiviti Menarik untuk Dilakukan:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Melawat Desa Dairy Farm","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Menikmati pemandangan Gunung Kinabalu","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bergambar di ladang dan kawasan berbukit","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lawatan ke Kundasang War Memorial","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nature walk dan menikmati udara segar","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Hotel / Resort Terbaik:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Spring Garden Kundasang","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Kinabalu Pine Resort","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sutera Sanctuary Lodges","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Genting Highland, Pahang","type":"text"}]},{"type":"image","attrs":{"alt":"tempat honeymoon di malaysia","src":"https://images.hellokahwin.com/inspire/tempat-honeymoon-di-malaysia/1787395685808-IN_E2_80_94TempatHoneymoondiMalaysia-GentingHighla/high.webp","title":null,"data-caption":"SOURCE: RESORT WORLD GENTING","data-caption-url":null}},{"type":"paragraph","content":[{"text":"Tempat honeymoon di Malaysia ini menawarkan honeymoon yang sejuk, meriah dan penuh hiburan, sesuai untuk pasangan yang mahukan percutian berbeza daripada pantai atau suasana sunyi.","type":"text"}]},{"type":"paragraph","content":[{"text":"Terletak di kawasan tanah tinggi yang dikelilingi hutan hujan, Genting menggabungkan keindahan alam dengan pusat hiburan bertaraf antarabangsa.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pelbagai tarikan menarik menanti seperti Genting Skyway, Skytropolis Theme Park, Ripley’s Adventure, Chin Swee Caves Temple, serta beli-belah dan hiburan di Resorts World Genting. Siang hari diisi dengan taman tema dan lawatan santai, manakala malam pula lebih hidup dengan restoran dan hiburan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Untuk pengalaman unik, pasangan juga boleh menikmati suasana sejuk luar biasa di Snow World. Ringkasnya, Genting Highlands sesuai untuk honeymoon yang aktif, fun dan penuh kejutan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Waktu Terbaik untuk Datang:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mac – September","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Waktu malam & awal pagi (cuaca lebih sejuk dan berkabus)","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Sesuai Untuk:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan yang sukakan honeymoon aktif & penuh hiburan","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pencinta taman tema, shopping dan nightlife","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Honeymoon ringkas tanpa perlu perjalanan jauh","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Aktiviti Menarik untuk Dilakukan:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Naik Genting Skyway dan menikmati pemandangan berkabus","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mencuba permainan di Skytropolis & Genting Highlands Theme Park","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Melawat Chin Swee Caves Temple","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bersiar-siar di SkyAvenue Mall & Premium Outlets","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Melawat Ripley’s Adventure & Snow World","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Makan malam romantik di restoran Resorts World Genting","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Hotel / Resort Terbaik:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Glamz","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Genting Crockford Hotel","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Resorts World Awana","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Ipoh, Perak","type":"text"}]},{"type":"paragraph","content":[{"text":"Ipoh sering dianggap sebagai permata tersembunyi yang sesuai untuk pasangan yang menginginkan honeymoon santai, klasik dan berjiwa tempatan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Digelar ","type":"text"},{"text":"“adik kecil Pulau Pinang”","type":"text","marks":[{"type":"italic"}]},{"text":", suasananya tenang, tidak sesak dan penuh karakter, mengingatkan Penang suatu ketika dahulu.","type":"text"}]},{"type":"paragraph","content":[{"text":"Bandar lama Ipoh dipenuhi bangunan kolonial, kedai lama berwarna-warni dan seni jalanan moden, menjadikannya seronok diterokai berdua.","type":"text"}]},{"type":"paragraph","content":[{"text":"Honeymoon di sini terasa lebih perlahan berjalan kaki di Old Town, menyusuri Cantonese Heritage Trail, menikmati kopi putih Ipoh dan mencuba pelbagai hidangan tempatan di kafe-kafe estetik yang romantik.","type":"text"}]},{"type":"paragraph","content":[{"text":"Waktu Terbaik untuk Datang:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mac – Oktober (cuaca lebih kering dan sesuai untuk berjalan kaki & aktiviti luar)","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Sesuai Untuk:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan yang sukakan honeymoon bandar santai & klasik","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pencinta makanan, kopi dan seni jalanan","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Honeymoon ringkas tanpa terlalu sesak","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Aktiviti Menarik untuk Dilakukan:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Melihat street art Ipoh dan lorong berwarna","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Menyusuri Old Town & Cantonese Heritage Trail","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Minum kopi putih Ipoh","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Meneroka kuil gua batu kapur","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lawatan ke Kellie’s Castle","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Teroka Gua Tempurung","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bersantai & berhibur di Lost World of Tambun","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jalan santai di tepi Sungai Kinta","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Hotel / Resort Terbaik:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The Banjaran Hotsprings Retreat, Perak","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tingkat Valley","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"TUI BLUE The Haven Ipoh","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Taman Negara, Pahang","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/tempat-honeymoon-di-malaysia/1787395687360-IN-TempatHoneymoondiMalaysia-TamanNegara/high.webp","title":null,"data-caption":"source: pahang tourism","data-caption-url":null}},{"type":"paragraph","content":[{"text":"Tempat honeymoon di Malaysia yang berikutnya adalah Taman Negara, Pahang. Lokasi ini menawarkan honeymoon yang unik, tenang dan penuh pengembaraan, sesuai untuk pasangan yang ingin lari daripada kesibukan bandar dan menikmati alam semula jadi.","type":"text"}]},{"type":"paragraph","content":[{"text":"Keindahan hutan hujan purba di sini menjadikan suasana lebih damai dan bermakna. Tarikan utama termasuk Canopy Walkway terpanjang di dunia dan pendakian ringan ke Bukit Teresek dengan pemandangan Gunung Tahan yang memukau.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pada waktu malam, pengalaman menjadi lebih mendebarkan melalui Night Safari, menyusuri hutan menaiki jeep sambil menyaksikan hidupan liar nokturnal dalam suasana sunyi dan misteri.","type":"text"}]},{"type":"paragraph","content":[{"text":"Waktu Terbaik untuk Datang:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mac – September (Musim lebih kering dan sesuai untuk aktiviti luar)","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Sesuai Untuk:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan yang sukakan honeymoon berkonsepkan alam & pengembaraan","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pencinta hutan, hidupan liar dan aktiviti eko-pelancongan","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Aktiviti Menarik untuk Dilakukan:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Titian kanopi","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Kembara gua","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Memancing","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mendaki gunung tahan","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lawatan ke penempatan Orang Asli dan Rapids Shooting","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lawatan ke Santuari Kelah Lubuk Tenor","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lawatan ke Lata Berkoh","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Hotel / Resort Terbaik:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mutiara Taman Negara Resort – Terletak di dalam kawasan taman negara","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tekemo Resort Taman Negara","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Xcape Resort @ Taman Negara","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Pulau Sibu, Johor","type":"text"}]},{"type":"paragraph","content":[{"text":"Pulau Sibu, atu Sibu Island, ialah sebuah pulau kecil yang tenang dan romantik di daerah Mersing, Johor, terletak kira-kira 12 kilometer dari tanah besar di perairan Laut China Selatan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Tempat honeymoon di Malaysia ini sangat sesuai untuk pasangan yang menginginkan honeymoon sunyi, intim dan dekat dengan alam semula jadi.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pulau ini terkenal dengan suasana santai seperti hammock di bawah pokok kelapa, pantai berpasir lembut dan laut jernih yang ideal untuk snorkeling serta scuba diving. Sebagai kawasan Marina Park, perairannya kaya dengan terumbu karang dan kehidupan marin, menjadikan aktiviti air antara tarikan utama.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pasangan juga boleh menikmati sea kayaking, berenang santai, menyaksikan sunset romantik atau melawat kampung nelayan untuk merasai budaya tempatan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Pulau Sibu terdiri daripada empat pulau kecil iaitu Pulau Sibu Besar, Pulau Sibu Tengah, Pulau Sibu Kukus dan Pulau Sibu Hujung yang sesuai untuk island hopping dan fotografi.","type":"text"}]},{"type":"paragraph","content":[{"text":"Waktu Terbaik untuk Datang:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mac – Oktober (Cuaca lebih baik, laut tenang dan sesuai untuk aktiviti air)","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Sesuai Untuk:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan yang mahukan honeymoon sunyi & penuh privasi","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pencinta pulau kecil, laut jernih dan suasana santai","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Honeymoon berkonsepkan alam semula jadi & island escape","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Aktiviti Menarik untuk Dilakukan:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Snorkeling & scuba diving di kawasan Marine Park","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sea kayaking dan jet ski","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Island hopping sekitar gugusan Pulau Sibu","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jungle trekking dalam hutan tropika","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Berehat di hammock sambil menikmati sunset","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Hotel / Resort Terbaik:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sea Gypsy Village Resort & Dive Base","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rimba Resort","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"MyVilla","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Melaka","type":"text"}]},{"type":"image","attrs":{"alt":"","src":"https://images.hellokahwin.com/inspire/tempat-honeymoon-di-malaysia/1787395689148-IN-TempatHoneymoondiMalaysia-Melaka/high.webp","title":null,"data-caption":"source: ck travels","data-caption-url":null}},{"type":"paragraph","content":[{"text":"Melaka menawarkan honeymoon berbeza dengan gabungan sejarah, budaya dan makanan. Bandar warisan dunia ini memikat dengan bangunan bersejarah, lorong-lorong lama yang berwarna-warni serta kafe-kafe cantik yang mencipta vibe tenang dan intim untuk dinikmati berdua.","type":"text"}]},{"type":"paragraph","content":[{"text":"Berjalan berpegangan tangan di sekitar ","type":"text"},{"text":"Jonker Street,","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"https://theweddingnotebook.com/inspire/real-weddings/bridal-portraits-set-against-gorgeous-blue-skies-at-pantai-klebang-and-jonker-walk-melaka/","class":null,"target":"_blank"}}]},{"text":" menyusuri Sungai Melaka dengan bot pada waktu senja, atau menikmati makan malam romantik berlatar bangunan kolonial menjadikan setiap momen terasa istimewa.","type":"text"}]},{"type":"paragraph","content":[{"text":"Apabila malam menjelma, cahaya lampu bandar lama dan alunan muzik jalanan menambah kehangatan suasana.","type":"text"}]},{"type":"paragraph","content":[{"text":"Waktu Terbaik untuk Datang:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mac – Jun","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"September – November (cuaca lebih selesa untuk berjalan kaki dan bersiar-siar)","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Sesuai Untuk:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan yang sukakan sejarah, budaya & food hunting","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Honeymoon santai tanpa perjalanan jauh","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan yang gemarkan suasana bandar lama","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Aktiviti Menarik untuk Dilakukan:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Melaka River Cruise waktu senja","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bersiar-siar di Jonker Street Night Market","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lawatan ke A Famosa & St. Paul’s Hill","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Trishaw ride berlampu neon","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Menikmati hidangan Nyonya dan kafe romantik","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Hotel / Resort Terbaik:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Casa del Rio Melaka","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The Majestic Melaka","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sojourn Spa Hotel Melaka","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Tanjung Aru, Kota Kinabalu","type":"text"}]},{"type":"image","attrs":{"alt":"tempat honeymoon di malaysia","src":"https://images.hellokahwin.com/inspire/tempat-honeymoon-di-malaysia/1787395690851-IN-TempatHoneymoondiMalaysia-TanjungAru/high.webp","title":null,"data-caption":"source: klook","data-caption-url":null}},{"type":"paragraph","content":[{"text":"Tanjung Aru adalah tempat honeymoon di Malaysia yang memikat hati, terkenal dengan sunset yang sering digelar antara tercantik di dunia.","type":"text"}]},{"type":"paragraph","content":[{"text":"Berlatar deretan pokok ru dan pasir pantai yang halus, setiap petang menyajikan pemandangan matahari terbenam yang melukis langit dengan warna merah, jingga dan ungu untuk mencipta suasana romantik yang sukar ditandingi.","type":"text"}]},{"type":"paragraph","content":[{"text":"Hanya beberapa minit dari pusat Kota Kinabalu dan lapangan terbang, Tanjung Aru mudah diakses namun terasa jauh dari hiruk-pikuk kota. Di sinilah pasangan boleh berjalan santai di tepi pantai, berehat di taman berhampiran, menikmati aktiviti air ringan atau sekadar duduk berdua menyaksikan senja.","type":"text"}]},{"type":"paragraph","content":[{"text":"Apabila malam tiba, Tanjung Aru berubah menjadi syurga makanan tempatan, dengan gerai yang menyajikan seafood bakar segar, sate, nasi lemak dan minuman kelapa sambil menikmati angin laut.","type":"text"}]},{"type":"paragraph","content":[{"text":"Waktu Terbaik untuk Datang:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Februari – September (Waktu terbaik untuk cuaca cerah dan sunset yang konsisten)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Waktu paling ideal: lewat petang hingga senja (sekitar 6.00 – 6.30 petang)","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Sesuai Untuk:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan pencinta sunset dan pantai","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Honeymoon santai tanpa bajet terlalu tinggi","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pasangan yang ingin gabungkan alam, makanan tempatan & suasana romantik","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Aktiviti Menarik untuk Dilakukan:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Menyaksikan sunset yang dianggap antara tercantik di dunia","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Berjalan santai di pantai dan Prince Philip Park","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Menikmati street food tempatan seperti seafood bakar dan sate","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Fotografi romantik ketika golden hour","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Aktiviti air seperti jet ski dan banana boat (musim tertentu)","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Hotel / Resort Terbaik:","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Shangri-La’s Tanjung Aru Resort & Spa","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The Magellan Sutera Resort","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bungaraya Island Resort","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Kesimpulan","type":"text"}]},{"type":"paragraph","content":[{"text":"Kesimpulannya, Malaysia ialah antara destinasi unik yang menawarkan pulau, tanah tinggi, hutan hujan dan bandar kolonial dalam satu negara. Lebih penting, ia sesuai untuk honeymoon romantik tanpa kos berlebihan.","type":"text"}]},{"type":"paragraph","content":[{"text":"Anda tidak perlu ke Eropah atau penerbangan jauh untuk mencipta kenangan istimewa kerana banyak tempat di Malaysia terasa eksklusif, intim dan cukup sempurna untuk memulakan bab baharu kehidupan bersama.","type":"text"}]},{"type":"paragraph","content":[{"text":"Artikel lain:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"20 Lokasi Terbaik Pre Wedding Photoshoot di Malaysia – Dari Alam Semula Jadi Hingga Urban City!","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"https://hellokahwin.com/lokasi-pre-wedding-photoshoot-terbaik/","class":null,"target":"_self"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"10 Dewan Kahwin Murah di Selangor & KL – Sesuai untuk Bajet Bawah RM5,000","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"https://hellokahwin.com/dewan-kahwin/","class":null,"target":"_self"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"20 Venue Garden Wedding Paling Cantik di Malaysia","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"https://hellokahwin.com/garden-wedding/","class":null,"target":"_self"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Majlis Perkahwinan Intim Bertemakan Warna Pastel Tropika di The Danna Langkawi","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"/artikel/minimalis-mewah/the-danna-langkawi","class":null,"target":"_self"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Majlis Perkahwinan Mewah dan Berkonsep Organik di Amankila, Bali","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"/artikel/glamor-eksklusif/amankila-bali","class":null,"target":"_self"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bajet Kahwin 2026: Apa yang Boleh Diharga Tepat, dan Apa yang Tidak","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener","href":"/artikel/venue-perancangan/bajet-kahwin","class":null,"target":"_self"}}]}]}]}]}]}'::jsonb where id = '3dcdff4c-d262-4333-8a75-4f826a207918';

